using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Underwater.Editor {
[InitializeOnLoad]public static class DolphinStallLiveCheck {
 const string Key="DolphinStallLiveCheck",Output="Renders/UserDolphinIssue/RecoveryLive/";static WreckCreature[] actors;static DolphinSwimController subject;static Vector3 previous;static float distance,maxStop,stop;static int beforeRecoveries,frames;static double began,next;static Camera camera;static bool failed;
 static DolphinStallLiveCheck(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=Changed;}
 public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");EditorApplication.EnterPlaymode();}
 static void Changed(PlayModeStateChange mode){if(mode==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool(Key,false)){SessionState.SetBool(Key,false);EditorApplication.Exit(failed?1:0);}}
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying||Time.timeSinceLevelLoad<2)return;try{
 if(actors==null){Directory.CreateDirectory(Output);actors=UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None).Where(a=>a.species==WreckCreature.Species.Dolphin).OrderBy(a=>a.name).ToArray();foreach(var a in actors)a.enabled=false;for(int f=0;f<9300;f++)foreach(var a in actors){a.Step(.05f,a.habitatCenter+new Vector3(3,.1f,3));a.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();}subject=actors[1].GetComponent<DolphinSwimController>();beforeRecoveries=subject.ClearanceRecoveries;previous=subject.GetComponent<ReefSphereBody>().WorldCenter;foreach(var a in actors)a.enabled=true;typeof(Diver).GetField("menu",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(Diver.Instance,false);camera=new GameObject("Temporary stall recovery camera").AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.enabled=true;camera.depth=Camera.main.depth+1;camera.fieldOfView=58;var anchor=subject.transform.position;camera.transform.position=anchor+new Vector3(5,3,4);camera.transform.LookAt(anchor);began=EditorApplication.timeSinceStartup;return;}
 var center=subject.GetComponent<ReefSphereBody>().WorldCenter;float moved=(center-previous).magnitude;previous=center;distance+=moved;stop=subject.ActualSpeed<.005f?stop+Time.deltaTime:0;maxStop=Mathf.Max(maxStop,stop);if(!subject.GetComponent<ReefSphereBody>().Clear(subject.transform.position))throw new Exception("Recovery overlapped reef");
 if(EditorApplication.timeSinceStartup>=next){next=EditorApplication.timeSinceStartup+.15;ReefCorrectionAudit.Capture(camera,Output+"Frame"+frames.ToString("D3")+".png");frames++;}
 if(EditorApplication.timeSinceStartup-began<22)return;if(subject.ClearanceRecoveries<=beforeRecoveries||distance<4||maxStop>2)throw new Exception("Actual stall location did not recover: events="+(subject.ClearanceRecoveries-beforeRecoveries)+" travel="+distance+" longest stop="+maxStop);File.WriteAllText(Output+"Validation.txt","Actual Play mode resumed at simulated 465 seconds, just before the reproduced coral pin.\nClearance recoveries="+(subject.ClearanceRecoveries-beforeRecoveries)+"; physical-centre travel="+distance+" m; longest stop="+maxStop+" s.\nReef collision checks passed; movement resumed through normal runtime updates.\n");File.WriteAllText(Output+"FrameCount.txt",frames.ToString());Debug.Log("DOLPHIN_STALL_LIVE_RECOVERED distance="+distance);EditorApplication.ExitPlaymode();
 }catch(Exception e){failed=true;Debug.LogException(e);EditorApplication.ExitPlaymode();}}
}
}
